import pandas as pd

df = pd.DataFrame({
    "order_id": [1, 2, 3, 2, 4, 1, 4, 3, 4],
    "status": ["paid", "paid", "failed", "refunded", "failed", "paid", "paid", "failed", "refunded"],
})
for order_id, group in sorted(df.groupby("order_id"), key=lambda item: item[0]):
    statuses = list(dict.fromkeys(group["status"]))
    if len(statuses) > 1:
        print(f"{order_id}: {' -> '.join(statuses)}")
print("exact duplicates removed:", int(df.duplicated(subset=["order_id", "status"]).sum()))
